class LRU:
    def __init__(self, cap):
        self._cap = cap
        self._d = {}

    def get(self, k, default=None):
        if k not in self._d:
            return default
        v = self._d.pop(k)
        self._d[k] = v
        return v
async def gather_limited(coros, *, limit=8):
    sem = asyncio.Semaphore(limit)
    async def _run(c):
        async with sem:
            return await c
    return await asyncio.gather(*(_run(c) for c in coros))
